 IEnumerator Snow(string scene,bool broad){SportsNavigation.LoadSport(scene);yield return null;yield return null;yield return new WaitForSecondsRealtime(.15f);var m=FindAnyObjectByType<SportsEventSession>();SaveKey(m.PreferenceKey);m.SetupScreen();m.NormalizeSetup();m.AllBots();if(broad)m.option=3;else if(m is LWS.TruckKeepaway.KeepawayMatch keep)keep.weatherChoice=3;else m.weather=3;Check(m.StartMatch(),scene+" snowy autonomous physical mode starts");yield return null;var snow=FindAnyObjectByType<SportsSnowSurface>();Check(snow!=null&&snow.Coverage>=.65f,scene+" snow round begins covered, not bare");Time.timeScale=2;float end=Time.realtimeSinceStartup+18;int contacts=0,broadContacts=0;while(Time.realtimeSinceStartup<end&&errors<15){contacts=Mathf.Max(contacts,snow.Contacts);broadContacts=Mathf.Max(broadContacts,snow.BroadContacts);snow.surface.Refresh();ControlledDepth();var generator=FindAnyObjectByType<NOT_Lonely.Weatherade.SRS_TraceMaskGenerator>();if(generator!=null)generator.SimOneStep();foreach(var c in m.cameras)if(c.enabled)c.Render();if(snow.surface.TraceMaskReady&&snow.surface.WheelTraceStampCount>30&&snow.surface.EnvironmentBindingsReady&&(broad?broadContacts>0:contacts>0))break;yield return null;}Check(snow.surface.SnowTextureReady&&snow.surface.TraceMaskReady&&snow.surface.EnvironmentBindingsReady,scene+" installed Weatherade textures/depth cameras/environment are ready: "+snow.surface.Diagnostic);Check(broad?broadContacts>0:contacts>0,scene+(broad?" genuine supported mattress contacts draw broad traces":" genuine NWH wheel contacts draw owned tire traces"));Check(snow.surface.WheelTraceStampCount>0,scene+" actual-contact trace stamps recorded="+snow.surface.WheelTraceStampCount);for(int k=0;k<12;k++){snow.surface.Refresh();ControlledDepth();var generator=FindAnyObjectByType<NOT_Lonely.Weatherade.SRS_TraceMaskGenerator>();if(generator!=null)generator.SimOneStep();foreach(var c in m.cameras)if(c.enabled)c.Render();yield return null;}snow.surface.Request