 IEnumerator Water(string scene){SportsNavigation.LoadSport(scene);yield return null;yield return null;yield return new WaitForSecondsRealtime(.15f);var m=FindAnyObjectByType<SportsEventSession>();SaveKey(m.PreferenceKey);m.SetupScreen();m.NormalizeSetup();m.AllBots();if(m is LWS.TruckLogRolling.LogMatch)m.setup.count=2;if(m is LWS.TruckDockDiving.DockMatch)m.setup.count=1;m.weather=1;Check(m.StartMatch(),scene+" real physical water mode starts");var fx=FindAnyObjectByType<SportsWaterInteraction>();Check(fx!=null&&fx.surface!=null&&fx.ripples.Length==48&&fx.spray.Length==8&&fx.audio.Length==4,scene+" bounded scene-owned interaction pools and real surface exist");if(fx==null){m.SetupScreen();yield break;}Time.timeScale=3;float end=Time.realtimeSinceStartup+75;bool replaySeen=false;int entries=0,wakes=0;while(Time.realtimeSinceStartup<end&&errors<20){entries=Math.Max(entries,fx.Entries);wakes=Math.Max(wakes,fx.Wakes);replaySeen|=fx.replay!=null&&fx.replay.Playing||fx.dockReplay!=null&&fx.dockReplay.Playing;if(scene=="TruckBogSnorkelling"&&entries>0&&wakes>2)break;if(scene=="TruckLogRolling"&&entries>1&&replaySeen)break;if(scene=="TruckDockDiving"&&entries>0&&replaySeen)break;yield return null;}Check(entries>0,scene+" actual body enters the real water surface, entries="+entries);if(scene=="TruckBogSnorkelling")Check(wakes>0,"actual Bog velocity/immersion produces continuing wakes="+wakes);else Check(replaySeen,scene+" physical water event reaches actual recorded replay");
 // Labelled camera-pose fixture: two cameras evaluate independently without global fog changes.
