 IEnumerator Start(){folder=SportsEvidencePaths.Folder("SharedSurfacesEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;Check(SystemInfo.graphicsDeviceType!=UnityEngine.Rendering.GraphicsDeviceType.Null,"actual graphics device available for trace readback");yield return Snow("TruckMattressRacing",true);yield return Snow("TruckKeepaway",false);yield return Water("TruckLogRolling");yield return Water("TruckBogSnorkelling");yield return Water("TruckDockDiving");SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindObjectsByType<AudioListener>().Length==1,"surface scene exits retain a single collection listener");Restore();log.AppendLine("ERRORS="+errors+". Real NWH/PhysX contacts, real vendor GPU trace readback/manual camera rendering and labelled camera-pose fixture. No hardware/human, normal-window/performance or audible-quality claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
